import React from 'react';
import { AiOutlineUser, AiOutlineBell } from 'react-icons/ai';

export default function Header() {
  return (
    <header className="bg-panel border-b border-border flex items-center justify-between px-6 py-4">
      {/* Левая часть — поиск */}
      <div className="flex items-center space-x-4 flex-1 max-w-xl">
        <input
          type="text"
          placeholder="Поиск по задачам, проектам, расписанию..."
          className="w-full bg-bg border border-border rounded px-3 py-2 text-primary placeholder-secondary focus:outline-none focus:ring-2 focus:ring-accentBlue"
        />
      </div>

      {/* Правая часть — статус и пользователь */}
      <div className="flex items-center space-x-4">
        <div className="flex items-center">
          <span className="w-2 h-2 bg-accentGreen rounded-full mr-1"></span>
          <span className="text-sm">Синхронизировано</span>
        </div>
        <div className="flex items-center">
          <span className="text-sm mr-1">Последняя проверка:</span>
          <span className="text-sm">сегодня 14:32</span>
        </div>
        <div className="flex items-center space-x-2">
          <AiOutlineUser className="h-5 w-5 text-secondary" />
          <span className="text-sm font-medium">Пользователь</span>
        </div>
        <div className="flex items-center space-x-2">
          <AiOutlineBell className="h-5 w-5 text-secondary" />
          <span className="text-sm">Онлайн</span>
        </div>
      </div>
    </header>
  );
}