import React, { useEffect, useState } from 'react';

const API = process.env.REACT_APP_API_BASE_URL;

export default function WeeklyChart() {
  const [weeks, setWeeks] = useState([]);

  useEffect(() => {
    fetch(`${API}/api/stats/weekly`)
      .then(r => r.json())
      .then(setWeeks)
      .catch(console.error);
  }, []);

  if (weeks.length === 0) {
    return <div className="h-32 bg-gray-800 rounded flex items-center justify-center text-secondary">Загрузка...</div>;
  }

  const maxHours = Math.max(...weeks.map(w => w.hours)) || 1;

  return (
    <div className="h-32 bg-gray-800 rounded relative">
      {weeks.map((w, idx) => {
        const heightPercent = ((w.hours / maxHours) * 80) + 20;
        return (
          <div
            key={w.label}
            className="absolute bottom-0 left-[calc(20%+_(idx*10%))] w-[10%] bg-accentBlue"
            style={{ height: `${heightPercent}%` }}
            title={`${w.label} неделя: ${w.hours} ч`}
          />
        );
      })}
    </div>
  );
}