import React, { useEffect, useState } from 'react';

const API = process.env.REACT_APP_API_BASE_URL;

export default function PlanFact() {
  const [planFact, setPlanFact] = useState({
    study: { plan: 0, fact: 0 },
    projects: { plan: 0, fact: 0 },
    self: { plan: 0, fact: 0 },
  });

  useEffect(() => {
    fetch(`${API}/api/stats/planfact`)
      .then(r => r.json())
      .then(setPlanFact)
      .catch(console.error);
  }, []);

  return (
    <div className="space-y-2">
      <div className="flex items-center justify-between text-sm">
        <span>План</span>
        <span>Факт</span>
      </div>

      {/* Study */}
      <div className="flex space-x-4">
        <div className="flex flex-col items-center">
          <div className="w-24 h-2 bg-gray-700 rounded">
            <div className="h-full bg-accentBlue" style={{ width: `${(planFact.study.plan / Math.max(planFact.study.plan, planFact.study.fact, 1)) * 100}%` }}></div>
          </div>
          <div className="text-xs mt-1">{planFact.study.plan} ч</div>
        </div>
        <div className="flex flex-col items-center ml-4">
          <div className="w-24 h-2 bg-gray-700 rounded">
            <div className="h-full bg-accentBlue" style={{ width: `${(planFact.study.fact / Math.max(planFact.study.plan, planFact.study.fact, 1)) * 100}%` }}></div>
          </div>
          <div className="text-xs mt-1">{planFact.study.fact} ч</div>
        </div>
      </div>

      {/* Projects */}
      <div className="flex space-x-4 mt-2">
        <div className="flex flex-col items-center">
          <div className="w-24 h-2 bg-gray-700 rounded">
            <div className="h-full bg-accentPurple" style={{ width: `${(planFact.projects.plan / Math.max(planFact.projects.plan, planFact.projects.fact, 1)) * 100}%` }}></div>
          </div>
          <div className="text-xs mt-1">{planFact.projects.plan} ч</div>
        </div>
        <div className="flex flex-col items-center ml-4">
          <div className="w-24 h-2 bg-gray-700 rounded">
            <div className="h-full bg-accentPurple" style={{ width: `${(planFact.projects.fact / Math.max(planFact.projects.plan, planFact.projects.fact, 1)) * 100}%` }}></div>
          </div>
          <div className="text-xs mt-1">{planFact.projects.fact} ч</div>
        </div>
      </div>

      {/* Self */}
      <div className="flex space-x-4 mt-2">
        <div className="flex flex-col items-center">
          <div className="w-24 h-2 bg-gray-700 rounded">
            <div className="h-full bg-accentGreen" style={{ width: `${(planFact.self.plan / Math.max(planFact.self.plan, planFact.self.fact, 1)) * 100}%` }}></div>
          </div>
          <div className="text-xs mt-1">{planFact.self.plan} ч</div>
        </div>
        <div className="flex flex-col items-center ml-4">
          <div className="w-24 h-2 bg-gray-700 rounded">
            <div className="h-full bg-accentGreen" style={{ width: `${(planFact.self.fact / Math.max(planFact.self.plan, planFact.self.fact, 1)) * 100}%` }}></div>
          </div>
          <div className="text-xs mt-1">{planFact.self.fact} ч</div>
        </div>
      </div>
    </div>
  );
}