import React, { useEffect, useState } from "react";

import Logo from "../assets/logo.svg";

import {
  FiHome,
  FiCalendar,
  FiCheck,
  FiFolder,
  FiBarChart2,
  FiAward,
  FiSettings,
  FiChevronLeft,
  FiChevronRight,
} from "react-icons/fi";

const Sidebar = ({ onSelect, activeSection }) => {
  const [collapsed, setCollapsed] = useState(() => {
    try {
      const item = localStorage.getItem("sidebarCollapsed");
      return item !== null ? JSON.parse(item) : false;
    } catch {
      return false;
    }
  });

  useEffect(() => {
    try {
      localStorage.setItem(
        "sidebarCollapsed",
        JSON.stringify(collapsed)
      );
    } catch (error) {
      console.warn(
        "Не удалось сохранить состояние сайдбара",
        error
      );
    }
  }, [collapsed]);

  const navItems = [
    { id: "dashboard", Icon: FiHome, label: "Главная" },
    { id: "schedule", Icon: FiCalendar, label: "Расписание" },
    { id: "tasks", Icon: FiCheck, label: "Задачи" },
    { id: "projects", Icon: FiFolder, label: "Проекты" },
    { id: "stats", Icon: FiBarChart2, label: "Статистика" },
    { id: "achievements", Icon: FiAward, label: "Достижения" },
    { id: "settings", Icon: FiSettings, label: "Настройки" },
  ];

  return (
    <aside
    className={`
      flex flex-col items-center
      ${collapsed ? "w-20" : "w-60"}
      h-fit
      m-4
      rounded-2xl
      overflow-hidden
      flex-shrink-0
      bg-panel
      border border-border
      transition-[width]
      duration-300
      ease-in-out
    `}
  >
      {/* Логотип */}
      <div
        className={`
          flex
          items-center
          transition-all
          duration-300
          ${collapsed
            ? "justify-center px-2 py-5"
            : "justify-start px-5 py-5"
          }
        `}
      >
        <img
          src={Logo}
          alt="XO_OS Logo"
          className="h-8 w-auto flex-shrink-0"
        />

        <span
          className={`
            ml-3
            text-sm
            font-bold
            whitespace-nowrap
            transition-all
            duration-200
            ${
              collapsed
                ? "opacity-0 w-0 ml-0"
                : "opacity-100 w-auto"
            }
          `}
        >
          XO_OS
        </span>
      </div>

      {/* Слоган */}
      <div
        className={`
          px-5
          text-center
          text-xs
          text-secondary
          overflow-hidden
          whitespace-nowrap
          transition-all
          duration-300
          ${
            collapsed
              ? "max-h-0 opacity-0 mb-0"
              : "max-h-10 opacity-100 mb-5"
          }
        `}
      >
        Учись. Развивайся. Достигай.
      </div>

      {/* Навигация */}
      <nav className="w-full px-3 space-y-1">
        {navItems.map(({ id, Icon, label }) => {
          const isActive = id === activeSection;

          return (
            <button
              key={id}
              onClick={() => onSelect(id)}
              className={`
                flex
                items-center
                w-full
                h-11
                rounded-lg
                transition-colors
                duration-200
                ${
                  isActive
                    ? "font-bold text-accentYellow bg-accentBlue/20"
                    : "text-primary hover:bg-accentBlue/10"
                }
              `}
              title={collapsed ? label : undefined}
            >
              <div
                className={`
                  flex
                  items-center
                  flex-shrink-0
                  transition-all
                  duration-300
                  ${
                    collapsed
                      ? "justify-center w-full"
                      : "justify-start w-full px-2"
                  }
                `}
              >
                <Icon className="h-5 w-5 flex-shrink-0" />

                <span
                  className={`
                    ml-3
                    whitespace-nowrap
                    overflow-hidden
                    transition-all
                    duration-200
                    ${
                      collapsed
                        ? "opacity-0 w-0 ml-0"
                        : "opacity-100 w-auto"
                    }
                  `}
                >
                  {label}
                </span>
              </div>
            </button>
          );
        })}
      </nav>

      {/* Google Calendar */}
      <div
        className={`
          mt-auto
          px-5
          pb-4
          overflow-hidden
          transition-all
          duration-300
          ${
            collapsed
              ? "opacity-0 max-h-0 px-0"
              : "opacity-100 max-h-40"
          }
        `}
      >
        <div className="mb-1 text-xs">
          Google Calendar
        </div>

        <div className="flex items-center">
          <span className="w-2 h-2 bg-accentGreen rounded-full mr-2" />

          <span className="text-xs">
            Синхронизировано
          </span>
        </div>

        <div className="mt-4 text-xs">
          Последняя синхронизация:
        </div>

        <div className="text-sm">
          Сегодня, 14:32
        </div>

        <div className="mt-2 text-xs">
          Версия:
        </div>

        <div className="font-mono text-xs">
          XO_OS v1.0.0
        </div>
      </div>

      {/* Кнопка сворачивания */}
      <button
        onClick={() => setCollapsed((value) => !value)}
        className={`
          mx-3
          mb-3
          h-9
          flex
          items-center
          justify-center
          rounded-lg
          bg-accentBlue/20
          hover:bg-accentBlue/30
          text-primary
          transition-colors
          duration-200
        `}
        title={
          collapsed
            ? "Развернуть меню"
            : "Свернуть меню"
        }
      >
        {collapsed ? (
          <FiChevronRight className="w-5 h-5" />
        ) : (
          <FiChevronLeft className="w-5 h-5" />
        )}
      </button>
    </aside>
  );
};

export default Sidebar;