import React, { useEffect, useState } from 'react';

const API = process.env.REACT_APP_API_BASE_URL;

export default function CalendarObsidianBlock() {
  const [calendar, setCalendar] = useState({
    status: '',
    lastSync: '',
    created: 0,
    updated: 0,
    moved: 0,
    deleted: 0,
  });
  const [obsidian, setObsidian] = useState({
    status: '',
    vault: '',
    lastSync: '',
  });

  useEffect(() => {
    // Google Calendar
    fetch(`${API}/api/calendar/status`)
      .then(r => r.json())
      .then(setCalendar)
      .catch(console.error);

    // Obsidian
    fetch(`${API}/api/obsidian/status`)
      .then(r => r.json())
      .then(setObsidian)
      .catch(console.error);
  }, []);

  return (
    <section className="bg-panel rounded-xl p-6 space-y-4">
      <div className="border-t border-border pt-4">
        <h3 className="text-lg font-bold mb-2">Google Calendar</h3>
        <div className="flex items-center">
          <span className="w-2 h-2 bg-accentGreen rounded-full mr-1"></span>
          <span>{calendar.status || 'Не активен'}</span>
        </div>
        <div className="mt-2 text-sm text-secondary">
          MAISync → Google Calendar
        </div>
        <div className="mt-2 text-sm text-secondary">
          Последняя синхронизация: {calendar.lastSync || 'Отсутствует'}
        </div>
        <div className="mt-2 flex space-x-2 text-xs">
          <div>Создано: {calendar.created}</div>
          <div>Обновлено: {calendar.updated}</div>
          <div>Перенесено: {calendar.moved}</div>
          <div>Удалено: {calendar.deleted}</div>
        </div>
      </div>

      <div className="border-t border-border pt-4">
        <h3 className="text-lg font-bold mb-2">Obsidian</h3>
        <div className="flex items-center">
          <span className="w-2 h-2 bg-accentGreen rounded-full mr-1"></span>
          <span>{obsidian.status || 'Отключён'}</span>
        </div>
        <div className="mt-2 text-sm text-secondary">
          Vault: {obsidian.vault}
        </div>
        <div className="mt-2 text-sm text-secondary">
          Последняя синхронизация: {obsidian.lastSync || "Отсутствует"}
        </div>
      </div>
    </section>
  );
}