import React, { useEffect, useState } from 'react';

const API = process.env.REACT_APP_API_BASE_URL;

export default function Achievements() {
  const [achievements, setAchievements] = useState([]);
  const [streak, setStreak] = useState(0);

  useEffect(() => {
    fetch(`${API}/api/achievements`)
      .then(r => r.json())
      .then(data => {
        setAchievements(data.achievements || []);
        setStreak(data.streak || 0);
      })
      .catch(console.error);
  }, []);

  return (
    <section className="bg-panel rounded-xl p-6 space-y-4">
      <h3 className="text-lg font-bold mb-3">Достижения</h3>
      <div className="flex flex-wrap gap-2">
        {achievements.map((a, idx) => (
          <span key={idx} className="bg-gray-800 px-3 py-1 rounded text-sm">
            {a.icon} {a.text}
          </span>
        ))}
      </div>

      <div className="mt-4 flex items-center">
        <h3 className="text-lg font-bold mr-2">Streak</h3>
        <span className="bg-accentYellow text-bg-dark px-3 py-1 rounded font-medium">
          🔥 {streak} дней подряд
        </span>
      </div>
    </section>
  );
}