import React, { useEffect, useState } from 'react';

const API = process.env.REACT_APP_API_BASE_URL;

export default function ScheduleList() {
  const [schedule, setSchedule] = useState([]);

  useEffect(() => {
    fetch(`${API}/api/schedule`)
      .then(r => r.json())
      .then(setSchedule)
      .catch(console.error);
  }, []);

  if (schedule.length === 0) {
    return (
      <section className="bg-panel rounded-xl p-6">
        <h2 className="text-xl font-bold mb-4">Ближайшие занятия</h2>
        <p className="text-center text-secondary">Данные не загружены</p>
      </section>
    );
  }

  return (
    <section className="bg-panel rounded-xl p-6">
      <h2 className="text-xl font-bold mb-4">Ближайшие занятия</h2>
      {schedule.map((item, idx) => (
        <div key={idx} className="flex items-center justify-between px-3 py-2 bg-gray-800 rounded mb-2">
          <div className="flex-1 min-w-[100px] font-mono">{item.time}</div>
          <div className={`inline-flex items-center px-2 py-1 text-xs rounded-full ${
            item.type === 'LECTURE'
              ? 'bg-accentBlue/20 text-accentBlue'
              : item.type === 'PRACTICE'
              ? 'bg-accentPurple/20 text-accentPurple'
              : item.type === 'LAB'
              ? 'bg-accentGreen/20 text-accentGreen'
              : 'bg-accentRed/20 text-accentRed'
          }`}>
            [{item.type === 'LECTURE' && '[Лекция]'}
            {item.type === 'PRACTICE' && '[Практика]'}
            {item.type === 'LAB' && '[Лабораторная]'}
            {item.type === 'EXAM' && '[Экзамен]'}]
          </div>
          <div className="flex-1 mx-4">{item.subject}</div>
          <div className="text-sm text-secondary">{item.room}</div>
          <div className="text-sm text-secondary">{item.teacher}</div>
          <div className={`px-2 py-0.5 text-xs rounded ${
            item.status === 'sync'
              ? 'bg-accentGreen/20 text-accentGreen'
              : 'bg-accentRed/20 text-accentRed'
          }`}>
            Синхр.
          </div>
        </div>
      ))}
    </section>
  );
}