import React, { useEffect, useState } from 'react';

const API = process.env.REACT_APP_API_BASE_URL;

export default function NowBlock() {
  const [now, setNow] = useState({
    taskTitle: '',
    taskDesc: '',
    timeEstimate: '',
    priority: '',
    xpReward: 0,
    time: '--:--',
  });

  useEffect(() => {
    fetch(`${API}/api/now`)
      .then(r => r.json())
      .then(setNow)
      .catch(console.error);
  }, []);
  return (
    <section className="bg-panel rounded-xl p-6 space-y-4">
      <div className="flex items-center justify-between">
        <h2 className="text-xl font-bold text-accentYellow">СЕЙЧАС</h2>
        <span className="text-sm text-secondary">{now.time}</span>
      </div>

      <div className="space-y-3 text-left">
        <h3 className="font-bold text-lg">{now.taskTitle}</h3>
        <p className="text-sm">{now.taskDesc}</p>
        <p className="text-sm">{now.timeEstimate}</p>
        <p className="text-sm text-xs">{now.priority}</p>
        <p className="font-semibold text-accentGreen">+{now.xpReward} XP</p>
      </div>

      <button
        className="w-full bg-accentBlue text-white font-bold py-2 px-4 rounded hover:bg-accentBlue/80 transition-colors"
      >
        НАЧАТЬ
      </button>
    </section>
  );
}