import React, { useEffect, useState } from 'react';

const API = process.env.REACT_APP_API_BASE_URL;

export default function DonutChart() {
  const [data, setData] = useState({ lecture: 0, practice: 0, lab: 0, total: 0 });

  useEffect(() => {
    fetch(`${API}/api/stats/semester`)
      .then(r => r.json())
      .then(setData)
      .catch(console.error);
  }, []);

  const total = data.total || 0;
  const lcPct = (data.lecture / total) * 100;
  const pzPct = (data.practice / total) * 100;
  const lrPct = (data.lab / total) * 100;

  return (
    <div className="relative w-24 h-24 mx-auto">
      <svg className="w-full h-full" viewBox="0 0 36 36" role="img">
        <circle className="stroke-gray-800 stroke-4" cx="18" cy="18" r="15.91549430918954" fill="none" />
        <circle
          className="stroke-accentBlue stroke-4"
          cx="18"
          cy="18"
          r="15.91549430918954"
          fill="none"
          strokeDasharray={`${lcPct}, 100`}
          transform="rotate(-90 18 18)"
        />
        <circle
          className="stroke-accentPurple stroke-4"
          cx="18"
          cy="18"
          r="15.91549430918954"
          fill="none"
          strokeDasharray={`${pzPct}, 100`}
          transform="rotate(-90 18 18)"
        />
        <circle
          className="stroke-accentGreen stroke-4"
          cx="18"
          cy="18"
          r="15.91549430918954"
          fill="none"
          strokeDasharray={`${lrPct}, 100`}
          transform="rotate(-90 18 18)"
        />
      </svg>

      <div className="absolute inset-0 flex flex-col items-center justify-center text-center">
        <div className="font-bold text-lg">{total} ч</div>
        <div className="text-xs text-secondary">Всего</div>
      </div>
    </div>
  );
}