import React, { useEffect, useState } from 'react';

const PlayerCard = () => {
  const [stats, setStats] = useState({
    level: 0,
    xp: 0,
    xpToNext: 500,
    focus: 0,
    energy: 0,
    discipline: 0,
    productivity: 0,
    avatarText: 'АВ',
  });

  useEffect(() => {
    // Example: fetch from /api/stats (you already have endpoint in backend)
    fetch('/api/stats')
      .then(res => res.json())
      .then(data => {
        // Expect shape: { level, total_xp, current_streak, max_streak, last_activity_date }
        // We'll compute xpToNext as (level+1)*1000 - total_xp
        const { level, total_xp } = data;
        setStats(prev => ({
          ...prev,
          level,
          xp: total_xp,
          xpToNext: (level + 1) * 1000 - total_xp,
        }));
      })
      .catch(console.error);
  }, []);

  return (
    <section className="bg-panel rounded-xl p-6 text-center space-y-4">
      <div className="flex items-center justify-center space-x-3">
        <div className="w-16 h-16 bg-accentBlue rounded-full flex items-center justify-center text-white font-bold">
          {stats.avatarText}
        </div>
        <div>
          <div className="text-xl font-bold">Уровень {stats.level}</div>
          <div className="text-sm text-secondary">Студент-исследователь</div>
        </div>
      </div>

      <div className="w-full bg-gray-800 rounded-full h-2.5 overflow-hidden">
        <div
          className="h-full bg-accentBlue"
          style={{ width: `${(stats.xp / (stats.xp + stats.xpToNext)) * 100}%` }}
        ></div>
      </div>

      <div className="text-sm text-secondary">
        {stats.xp} / {stats.xp + stats.xpToNext} XP
      </div>

      {/* 4 характеристики */}
      <div className="grid grid-cols-2 gap-4 text-sm">
        <div className="flex flex-col items-center">
          <span className="font-medium">Focus</span>
          <span className="mt-1">{stats.focus} / 100</span>
        </div>
        <div className="flex flex-col items-center">
          <span className="font-medium">Energy</span>
          <span className="mt-1">{stats.energy} / 100</span>
        </div>
        <div className="flex flex-col items-center">
          <span className="font-medium">Discipline</span>
          <span className="mt-1">{stats.discipline} / 100</span>
        </div>
        <div className="flex flex-col items-center">
          <span className="font-medium">Productivity</span>
          <span className="mt-1">{stats.productivity} / 100</span>
        </div>
      </div>
    </section>
  );
};

export default PlayerCard;