import React, { useState, useEffect } from 'react';

const API = process.env.REACT_APP_API_BASE_URL;

export default function TopSubjects() {
  const [subjects, setSubjects] = useState([]);
  const [mode, setMode] = useState('hours'); // hours | lessons | xp | tasks

  useEffect(() => {
    fetch(`${API}/api/stats/topsubjects`)
      .then(r => r.json())
      .then(setSubjects)
      .catch(console.error);
  }, []);

  const toggle = m => () => setMode(m);

  const getValue = subj => {
    switch (mode) {
      case 'lessons': return Math.round(subj.hours / 1.5); // approximations
      case 'xp': return subj.hours * 10;
      case 'tasks': return Math.round(subj.hours / 2);
      default: return subj.hours;
    }
  };

  if (subjects.length === 0) {
    return <p className="text-center text-secondary">Данные не загружены</p>;
  }

  const maxValue = Math.max(...subjects.map(getValue)) || 1;

  return (
    <div>
      <div className="flex justify-between items-center mb-2">
        <h3 className="text-lg font-bold">Топ предметов</h3>
        <div className="flex space-x-2 text-xs">
          <button onClick={toggle('hours')} className={`px-2 py-1 rounded ${mode === 'hours' ? 'bg-accentBlue/20' : 'hover:bg-accentBlue/10'}`}>
            Часы
          </button>
          <button onClick={toggle('lessons')} className={`px-2 py-1 rounded ${mode === 'lessons' ? 'bg-accentPurple/20' : 'hover:bg-accentPurple/10'}`}>
            Занятия
          </button>
          <button onClick={toggle('xp')} className={`px-2 py-1 rounded ${mode === 'xp' ? 'bg-accentGreen/20' : 'hover:bg-accentGreen/10'}`}>
            XP
          </button>
          <button onClick={toggle('tasks')} className={`px-2 py-1 rounded ${mode === 'tasks' ? 'bg-accentYellow/20' : 'hover:bg-accentYellow/10'}`}>
            Выполненные задачи
          </button>
        </div>
      </div>

      <div className="space-y-2">
        {subjects.map((subj, idx) => (
          <div key={idx} className="flex items-center justify-between px-3 py-2 bg-gray-800 rounded">
            <span className="flex-1">{subj.name}</span>
            <div className="w-24 h-2 bg-gray-700 rounded">
              <div className="h-full bg-accentBlue" style={{ width: `${(getValue(subj) / maxValue) * 100}%` }}></div>
            </div>
            <span className="text-right">{getValue(subj)} {mode === 'hours' ? 'ч' : ''}</span>
          </div>
        ))}
      </div>
    </div>
  );
}