import React from 'react';
import DonutChart from './StatsSection/DonutChart';
import WeeklyChart from './StatsSection/WeeklyChart';
import PlanFact from './StatsSection/PlanFact';
import TopSubjects from './StatsSection/TopSubjects';

export default function StatsSection() {
  return (
    <section className="bg-panel rounded-xl p-6 space-y-6">
      <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
        {/* Нагрузка семестра */}
        <div className="col-span-2">
          <div className="flex items-center justify-between mb-2">
            <h3 className="text-lg font-bold">Нагрузка семестра</h3>
          </div>
          <div className="flex flex-col items-center">
            <DonutChart />
            <div className="mt-2 text-sm text-secondary space-y-1">
              {/* Показываем подписи под графиком – можно взять из состояния DonutChart */}
              <div>ЛК: … ч</div>
              <div>ПЗ: … ч</div>
              <div>ЛР: … ч</div>
            </div>
          </div>
        </div>

        {/* Динамика по неделям */}
        <div>
          <h3 className="text-lg font-bold">Динамика по неделям</h3>
          <WeeklyChart />
        </div>

        {/* Топ предметов */}
        <div>
          <TopSubjects />
        </div>

        {/* План vs Факт */}
        <div className="col-span-2">
          <h3 className="text-lg font-bold">План vs Факт</h3>
          <PlanFact />
        </div>
      </div>
    </section>
  );
}